argv:
$ErrorActionPreference='Stop';
$repo='E:\WebAIBridge';
$expectedHead='e8033f2e42bd335c10a397eb3d2cb62c8bb837a9';
$files=@('app/scripts/operator-lifecycle-r40.ps1','app/scripts/pause-all-r40.cmd','app/scripts/pause-browser-r40.cmd','app/scripts/resume-attach-r40.cmd','app/scripts/resume-managed-r40.cmd');
$git=(Get-Command git.exe -CommandType Application -ErrorAction Stop | Select-Object -First 1).Path;
$head=((@(& $git -C $repo rev-parse HEAD))-join '').Trim();
if($head -ne $expectedHead){throw ('Unexpected HEAD before quarantine: '+$head)}
$status=@(& $git -C $repo status --short);
$expected=@($files|ForEach-Object{' M '+$_});
$statusNorm=($status|Sort-Object) -join [Environment]::NewLine;
$expectedNorm=($expected|Sort-Object) -join [Environment]::NewLine;
if($statusNorm -ne $expectedNorm){throw ('Dirty set changed; refusing quarantine/restore. Observed: '+($status -join '; '))}
$stamp=(Get-Date).ToUniversalTime().ToString('yyyyMMddTHHmmssZ');
$root=Join-Path $repo ('app\data\backups\r42-dirty-quarantine-'+$stamp);
New-Item -ItemType Directory -Force -Path $root|Out-Null;
$entries=@();
foreach($f in $files){$src=Join-Path $repo $f;if(!(Test-Path -LiteralPath $src)){throw ('Missing dirty file: '+$f)};$safe=($f -replace '[\\/:*?"<>|]','_');$dst=Join-Path $root $safe;Copy-Item -LiteralPath $src -Destination $dst -Force;$entries += [ordered]@{path=$f;backup=$dst;sha256=(Get-FileHash -LiteralPath $src -Algorithm SHA256).Hash.ToLowerInvariant()}}
$manifest=Join-Path $root 'manifest.json';
[ordered]@{object='r42.dirty_quarantine.v1';createdAt=(Get-Date).ToUniversalTime().ToString('o');head=$head;files=$entries}|ConvertTo-Json -Depth 8|Set-Content -LiteralPath $manifest -Encoding UTF8;
& $git -C $repo restore --worktree -- @files;
if($LASTEXITCODE -ne 0){throw ('git restore failed: '+$LASTEXITCODE)}
$after=@(& $git -C $repo status --short);
if($after.Count -ne 0){throw ('Worktree still dirty after targeted restore: '+($after -join '; '))}
[pscustomobject]@{status='QUARANTINED_AND_CLEAN';head=$head;quarantineRoot=$root;manifest=$manifest;files=$entries;dirtyAfter=$after.Count}|ConvertTo-Json -Depth 8 -Compress
